#include <iostream>
#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

/**
 * Problem: 21964 - Fill the Containers
 * 
 * 解題思路：
 * 1. 給定 n 個裝有牛奶的瓶子和 m 個容器，按順序將瓶子中的牛奶倒入容器。
 * 2. 目標是最小化所有容器中最大容量的那個值。
 * 3. 由於最大容量與是否能裝下所有牛奶具有單調性，我們可以使用二分搜尋來尋找答案。
 * 4. 二分搜尋範圍：
 *    - 下限 (low)：單個瓶子的最大值（因為每個瓶子必須完整倒入一個容器）。
 *    - 上限 (high)：所有瓶子的總和（所有瓶子倒進同一個容器）。
 * 5. 對於每個中間值 mid，我們模擬裝瓶過程：
 *    - 如果當前容器裝不下下一個瓶子，就換一個新容器。
 *    - 如果所需容器數 <= m，則 mid 是可行的，嘗試更小的值。
 */

bool canFill(const vector<int>& vessels, int m, int capacity) {
    int current_sum = 0;
    int containers_used = 1;
    for (int v : vessels) {
        if (current_sum + v > capacity) {
            containers_used++;
            current_sum = v;
            if (containers_used > m) return false;
        } else {
            current_sum += v;
        }
    }
    return true;
}

int main() {
    int n, m;
    while (cin >> n >> m) {
        vector<int> vessels(n);
        int max_v = 0;
        long long sum_v = 0;
        for (int i = 0; i < n; i++) {
            cin >> vessels[i];
            max_v = max(max_v, vessels[i]);
            sum_v += vessels[i];
        }

        int low = max_v, high = (int)1e9; // 1e9 足夠大，因為 sum_v 可能超過 int
        if (sum_v < high) high = (int)sum_v;
        int ans = high;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (canFill(vessels, m, mid)) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        cout << ans << endl;
    }
    return 0;
}
